import re, glob
allowed = ['Nemec','Gerber','Dieckman','Tooley','Zuckerberg','Wal-Mart','Zimmerman',
           '18-1101','18-1001','18-1002','18-1003','8106','8-106']
pattern = re.compile(r'\b(?:[A-Z][a-zA-Z]+(?: v\. [A-Z][a-zA-Z .&]+)?)\b|[Ss]ection \d+|\d+ Del\. C\.[^;,.]*|[0-9]{1,2} A\.3d [0-9]+|[0-9]{3} A\.2d [0-9]+|[0-9]{4} Del\.[A-Z ]+LE?XT?R')
