    hits = set()
    for m in re.finditer(r'([A-Z][a-zA-Z]+)\s+v\.\s+([A-Za-z ,.&\'-]+)', text):
        hits.add(m.group(0).split(',')[0])
    for m in re.finditer(r'(\d+ A\.3d \d+|\d+ A\.2d \d+)', text):
        hits.add(m.group(1))
    for h in sorted(hits):
        if not any(a.split()[0].lower() in h.lower() or a.lower() in h.lower() for a in allowed):
            reported.add(f+': '+h)
print('Outside-authority hits:', reported if reported else 'NONE')
